import { authoredLesson, type LessonOverrideLibrary } from "./chapterPlanHelpers";

/**
 * JavaScript gap lessons for concepts the chapter plans named but the shipped code never showed.
 *
 * Unlike the Java and C++ libraries, every program here is executed for real: the app's own
 * JavaScript runner is a Worker sandbox, and `src/data/javascriptRuntime.test.ts` feeds every
 * example, starter, solution, and project through that same shipped worker source and compares the
 * result with the declared output on every test run. The outputs below were recorded from the real
 * sandbox while these lessons were written, not predicted, and the runner's own limits appear where
 * they matter: the sandbox reports output once the synchronous code and the microtask queue have
 * drained, so the event-loop lesson describes the macrotask phase instead of printing it.
 */

const gapMistakes: Example["mistakes"] = [
  { mistake: "Comparing with == because the operands look similar", error: "A conversion makes unequal values compare equal", fix: "Use === and convert explicitly at the point where a conversion is intended." },
  { mistake: "Passing an object method to a callback without binding it", error: "this is undefined inside the callback and the object's state is unreachable", fix: "Bind the method or pass an arrow function that closes over the object." },
  { mistake: "Testing only a comfortable middle value", error: "The boundary case is the one that breaks, and it ships untested", fix: "Add the value where the comparison changes branch to the test table." },
  { mistake: "Placing a value into markup or statement text by concatenation", error: "The value changes the structure instead of being displayed or compared", fix: "Escape before markup, and pass values as parameters rather than as text." },
];

const example = (title: string, code: string, output: string, explanation: string, lines: string[]): Example => ({
  title,
  code,
  output,
  explanation,
  lines,
  mistakes: gapMistakes,
});

